const items = $input.all();

// Expresiones afirmativas
const afirmativas = [
  "si", "sí", "claro", "claro que si", "claro que sí",
  "por supuesto", "desde luego", "correcto", "exacto",
  "afirmativo", "asi es", "así es", "efectivamente",
  "de acuerdo", "estoy de acuerdo", "ok", "okay", "okey",
  "vale", "bueno", "listo", "dale", "de una",
  "hagale", "hágale", "confirmo", "confirmado",
  "acepto", "estoy de acuerdo", "me parece bien",
  "esta bien", "está bien", "perfecto", "excelente",
  "si señor", "sí señor", "si señora", "sí señora",
  "por mi esta bien", "por mí está bien",
  "cuenta conmigo", "sin problema", "no hay problema",
  "con gusto", "obvio", "obviamente", "seguro",
  "seguro que si", "seguro que sí", "así será",
  "de acuerdo contigo", "estoy listo", "estoy lista",
  "si quiero", "sí quiero", "quiero", "si deseo",
  "sí deseo", "deseo", "me interesa", "estoy interesado",
  "estoy interesada", "me apunto", "vamos", "hagámoslo",
  "adelante", "proceda", "proceder", "autorizo",
  "doy mi consentimiento", "si acepto", "sí acepto",
  "si confirmo", "sí confirmo", "correcto gracias"
];

// Expresiones negativas
const negativas = [
  "no", "no gracias", "no quiero", "no deseo",
  "no acepto", "no estoy de acuerdo", "negativo",
  "para nada", "de ninguna manera", "en absoluto",
  "no me interesa", "no me sirve", "no puedo",
  "no deseo participar", "no deseo continuar",
  "no estoy interesado", "no estoy interesada",
  "no por ahora", "ahora no", "por ahora no",
  "me niego", "rechazo", "no autorizo",
  "no doy mi consentimiento", "no confirmo",
  "no asistiré", "no voy", "no puedo asistir",
  "no quiero participar", "no quiero hacerlo",
  "prefiero que no", "mejor no", "para otro momento",
  "en otra ocasión", "no estoy disponible",
  "no me queda bien", "no me parece",
  "no estoy seguro", "no estoy segura",
  "no lo creo", "de ninguna forma",
  "ni hablar", "jamás", "nunca", "no deseo hacerlo",
  "no estoy de acuerdo contigo", "no me interesa gracias"
];

// Obtener el mensaje desde la estructura habitual de Evolution API
return items.map(item => {
  const data = item.json;

  const mensaje = String(
    data.body?.data?.message?.conversation ??
    data.body?.data?.message?.extendedTextMessage?.text ??
    data.data?.message?.conversation ??
    data.data?.message?.extendedTextMessage?.text ??
    data.mensaje ??
    data.text ??
    ""
  ).trim();

  const normalizar = texto => texto
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[¿?¡!.,;:]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  const texto = normalizar(mensaje);

  const afirmativasNorm = afirmativas.map(normalizar);
  const negativasNorm = negativas.map(normalizar);

  let intencion = "desconocida";

  // Coincidencia exacta para evitar clasificar frases ambiguas
  if (negativasNorm.includes(texto)) {
    intencion = "negativa";
  } else if (afirmativasNorm.includes(texto)) {
    intencion = "afirmativa";
  }

  return {
    json: {
      ...data,
      mensaje_original: mensaje,
      mensaje_normalizado: texto,
      intencion,
      requiere_ia: intencion === "desconocida"
    }
  };
});
